import * as T from 'three';
import {SPEC,TIERS,direction,attentionDirection,hash} from '../assets/latent-field/runtime.js';
export function createFibers(lod){
 const count=TIERS[lod].visual_fibers,group=new T.Group();group.name='FX_GLASS_FIELD';if(!count)return group;
 const positions=[],normals=[],along=[],seeds=[],tips=[],tipSeeds=[];
 for(let i=0;i<count;i++){
  const d=new T.Vector3(...direction(i,count)),t=new T.Vector3().crossVectors(d,Math.abs(d.y)<.9?new T.Vector3(0,1,0):new T.Vector3(1,0,0)).normalize(),start=3.1+hash(i+111)*3.4,end=16+Math.pow(hash(i+712),4)*.65;
  const point=u=>d.clone().multiplyScalar(T.MathUtils.lerp(start,end,u)).addScaledVector(t,.07*Math.sin(u*Math.PI)*(hash(i+30)-.5));
  for(let j=0;j<3;j++)for(const u of[j/3,(j+1)/3]){positions.push(...point(u).toArray());normals.push(...d.toArray());along.push(u);seeds.push(hash(i+9));}
  tips.push(...point(1).toArray());tipSeeds.push(hash(i+40));
 }
 const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));g.setAttribute('radial',new T.Float32BufferAttribute(normals,3));g.setAttribute('along',new T.Float32BufferAttribute(along,1));g.setAttribute('seed',new T.Float32BufferAttribute(seeds,1));
 const vertex=`attribute vec3 radial;attribute float along;attribute float seed;varying float vAlong;varying float vSeed;varying float vRim;varying float vKey;void main(){vec4 world=modelMatrix*vec4(position,1.);vec3 n=normalize(mat3(modelMatrix)*radial);vec3 eye=normalize(cameraPosition-world.xyz);vRim=pow(1.-abs(dot(n,eye)),1.8);vKey=max(dot(n,normalize(vec3(.7,.8,-.25))),0.);vAlong=along;vSeed=seed;gl_Position=projectionMatrix*viewMatrix*world;}`;
 const mat=new T.ShaderMaterial({vertexShader:vertex,fragmentShader:`varying float vAlong;varying float vSeed;varying float vRim;varying float vKey;void main(){float rim=(.055+.95*vRim)*(.20+.80*vKey);float strand=.25+pow(vSeed,3.)*.75;float glint=pow(.5+.5*sin(vAlong*290.+vSeed*120.),26.);vec3 silver=vec3(.31,.43,.37);vec3 c=vec3(.004,.010,.007)+silver*rim*strand*(.18+glint*.8)*pow(vAlong,2.);gl_FragColor=vec4(c,.34+.40*vRim);}`,transparent:true,depthWrite:false,depthTest:true});
 const lines=new T.LineSegments(g,mat);lines.name='FX_DORMANT_STRANDS';group.add(lines);
 const points=new T.BufferGeometry();points.setAttribute('position',new T.Float32BufferAttribute(tips,3));points.setAttribute('seed',new T.Float32BufferAttribute(tipSeeds,1));
 const tipMat=new T.ShaderMaterial({transparent:true,depthWrite:false,vertexShader:`attribute float seed;varying float vLight;void main(){vec4 world=modelMatrix*vec4(position,1.);vec3 n=normalize(mat3(modelMatrix)*normalize(position));float rim=pow(1.-abs(dot(n,normalize(cameraPosition-world.xyz))),2.);vLight=(.03+.97*rim)*(.18+.82*max(dot(n,normalize(vec3(.7,.8,-.25))),0.))*pow(seed,2.);gl_PointSize=.7+pow(seed,3.)*1.8;gl_Position=projectionMatrix*viewMatrix*world;}`,fragmentShader:`varying float vLight;void main(){float r=length(gl_PointCoord-.5)*2.;if(r>1.)discard;gl_FragColor=vec4(vec3(.36,.47,.40)*vLight,(1.-r*r)*.75);}`});const glints=new T.Points(points,tipMat);glints.name='FX_REFLECTIVE_TIPS';group.add(glints);return group;
}
export function createAttention(){
 const group=new T.Group();group.name='FX_EMERALD_ATTENTION';const segments=8,p=new Float32Array(48*segments*2*3),c=new Float32Array(p.length),tipP=new Float32Array(48*3),levels=new Float32Array(48);const lineGeometry=new T.BufferGeometry();lineGeometry.setAttribute('position',new T.BufferAttribute(p,3).setUsage(T.DynamicDrawUsage));lineGeometry.setAttribute('color',new T.BufferAttribute(c,3).setUsage(T.DynamicDrawUsage));const lines=new T.LineSegments(lineGeometry,new T.LineBasicMaterial({vertexColors:true,transparent:true,opacity:.8,blending:T.AdditiveBlending,depthWrite:false,toneMapped:false}));lines.frustumCulled=false;group.add(lines);
 const tipGeometry=new T.BufferGeometry();tipGeometry.setAttribute('position',new T.BufferAttribute(tipP,3).setUsage(T.DynamicDrawUsage));tipGeometry.setAttribute('level',new T.BufferAttribute(levels,1).setUsage(T.DynamicDrawUsage));
 const halo=new T.Points(tipGeometry,new T.ShaderMaterial({transparent:true,depthTest:true,depthWrite:false,blending:T.AdditiveBlending,vertexShader:`attribute float level;varying float vLevel;void main(){vLevel=level;vec4 p=modelViewMatrix*vec4(position,1.);gl_PointSize=(9.+7.*level)*min(1.8,65./max(20.,-p.z));gl_Position=projectionMatrix*p;}`,fragmentShader:`varying float vLevel;void main(){vec2 uv=gl_PointCoord-.5;float r=length(uv)*2.;if(r>1.||vLevel<.001)discard;float glow=exp(-r*r*8.)*(1.-smoothstep(.7,1.,r));gl_FragColor=vec4(vec3(.18,1.,.42)*glow*vLevel,.40);}`}));halo.frustumCulled=false;group.add(halo);
 return {group,update(states){for(let i=0;i<48;i++){const d=attentionDirection(i),s=states[i];for(let j=0;j<segments;j++)for(let k=0;k<2;k++){const a=(j+k)/segments,offset=(i*segments*2+j*2+k)*3,length=SPEC.root_radius_m+s.length*a,pulse=.45+.55*Math.exp(-Math.pow((a-((s.u*1.4)%1))*7,2)),level=s.level*pulse*2.1;for(let q=0;q<3;q++)p[offset+q]=d[q]*length;c.set([level*.18,level,level*.38],offset);}for(let q=0;q<3;q++)tipP[i*3+q]=d[q]*(SPEC.root_radius_m+s.length);levels[i]=s.level;}lineGeometry.attributes.position.needsUpdate=lineGeometry.attributes.color.needsUpdate=tipGeometry.attributes.position.needsUpdate=tipGeometry.attributes.level.needsUpdate=true;}};
}
export function createFog(){
 const uniforms={uTime:{value:0},uAmount:{value:1},uInverseProjection:{value:new T.Matrix4()},uCameraWorld:{value:new T.Matrix4()},uEye:{value:new T.Vector3()}};
 const material=new T.ShaderMaterial({uniforms,depthWrite:false,depthTest:false,vertexShader:`varying vec2 vUv;void main(){vUv=uv;gl_Position=vec4(position.xy,1.,1.);}`,fragmentShader:`precision highp float;varying vec2 vUv;uniform float uTime;uniform float uAmount;uniform mat4 uInverseProjection;uniform mat4 uCameraWorld;uniform vec3 uEye;
float hash(vec3 p){p=fract(p*.1031);p+=dot(p,p.yzx+33.33);return fract((p.x+p.y)*p.z);}
float noise(vec3 p){vec3 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(mix(hash(i),hash(i+vec3(1,0,0)),f.x),mix(hash(i+vec3(0,1,0)),hash(i+vec3(1,1,0)),f.x),f.y),mix(mix(hash(i+vec3(0,0,1)),hash(i+vec3(1,0,1)),f.x),mix(hash(i+vec3(0,1,1)),hash(i+vec3(1,1,1)),f.x),f.y),f.z);}
void main(){vec4 r=uInverseProjection*vec4(vUv*2.-1.,1.,1.);vec3 ray=normalize(mat3(uCameraWorld)*(r.xyz/r.w));vec3 sum=vec3(0.);float phase=uTime*6.2831853/48.;vec3 flow=vec3(sin(phase)*.28,cos(phase)*.2,0.);for(int i=0;i<12;i++){float t=32.+float(i)*6.;vec3 p=uEye+ray*t-vec3(0.,25.,0.);float n=noise(p*.09+flow)*.50+noise(p*.25-flow)*.30+noise(p*.65+flow)*.20;float density=pow(smoothstep(.43,.78,n),2.)*exp(-dot(p,p)/2100.);float outside=smoothstep(15.,21.,length(p));float light=exp(-length(p-vec3(26.,19.,-10.))*.025);sum+=vec3(.055,.105,.075)*density*outside*light*.21;}float vignette=1.-.55*pow(length((vUv-.5)*1.3),2.);gl_FragColor=vec4((vec3(.001,.003,.002)+sum*uAmount)*vignette,1.);}`});const mesh=new T.Mesh(new T.PlaneGeometry(2,2),material);mesh.name='FX_VOLUMETRIC_BACKDROP';mesh.frustumCulled=false;mesh.renderOrder=-1000;return {mesh,update(camera,time,amount){uniforms.uTime.value=time;uniforms.uAmount.value=amount;uniforms.uEye.value.copy(camera.position);uniforms.uInverseProjection.value.copy(camera.projectionMatrixInverse);uniforms.uCameraWorld.value.copy(camera.matrixWorld);}};
}
